"use client";

import React from "react";
import { Heading } from "../components/atoms/Heading";
import { CategoryCard } from "@/src/components/molecules/CategoryCard";
import { Footer } from "../components/organisms/Footer";
import { HeaderDashboard } from "../components/organisms/HeaderDashboard";
import { ProductSection } from "../components/organisms/ProductSection";
import { PromoBanner } from "../components/organisms/PromoBanner";
import { categories } from "../lib/data/categories";
import { getProductsByCategory, getRecommendedProducts } from "../lib/data/products";

export default function Dashboard() {
  function handleSearch(keyword: string) {
    alert(`Anda mencari: ${keyword}`);
  }

  return (
    <>
      <HeaderDashboard onSearch={handleSearch} />
        <main>
          <PromoBanner />

          <div>
            <Heading level={1} className="text-xl">
              Kategori Utama
            </Heading>
            <div className="flex w-full flex-row justify-around py-6">
              {categories.map((category) => (
                <CategoryCard 
                  key={category.slug}
                  category={category}
                />
              ))}
            </div>
          </div>

          <ProductSection 
            title="Rekomendasi"
            subtitle="Lihat lebih lanjut"
            products={getRecommendedProducts()}
          />
          <ProductSection 
            title="Makanan Anjing"
            products={getProductsByCategory("makanan-anjing")}
          />
          <ProductSection 
            title="Makanan Kucing"
            products={getProductsByCategory("makanan-kucing")}
          />
          <ProductSection
            title="Perlengkapan Hewan"
            products={getProductsByCategory("aksesoris-dan-mainan")}
          />
        </main>

      <Footer />
    </>
  );
} 